export class PerformanceMonitor {
  constructor() {
    this.fps = 60;
    this.frameMs = 16.7;
    this.drawMs = 0;
    this.updateMs = 0;
    this.alpha = 0.08;
  }

  sampleFrame(dt) {
    const instant = dt > 0 ? 1 / dt : 60;
    this.fps += (instant - this.fps) * this.alpha;
    this.frameMs += (dt * 1000 - this.frameMs) * this.alpha;
  }

  sampleUpdate(ms) {
    this.updateMs += (ms - this.updateMs) * this.alpha;
  }

  sampleDraw(ms) {
    this.drawMs += (ms - this.drawMs) * this.alpha;
  }
}

import { WORLD } from '../core/constants.js';
import { classifyBiome, SPEC_BIOME_IDS } from './biomes.js';

const cache = new Map();

export function auditBiomesAround(player, sampleChunks = 96, strideChunks = 4) {
  const pcx = Math.floor(player.x / WORLD.chunkSize);
  const pcy = Math.floor(player.y / WORLD.chunkSize);
  const bucketX = Math.floor(pcx / 8) * 8;
  const bucketY = Math.floor(pcy / 8) * 8;
  const key = `${bucketX},${bucketY},${sampleChunks},${strideChunks}`;
  if (cache.has(key)) return cache.get(key);

  const counts = new Map();
  for (let cy = bucketY - sampleChunks / 2; cy <= bucketY + sampleChunks / 2; cy += strideChunks) {
    for (let cx = bucketX - sampleChunks / 2; cx <= bucketX + sampleChunks / 2; cx += strideChunks) {
      const wx = Math.floor(cx * WORLD.chunkSize + WORLD.chunkSize / 2);
      const wy = Math.floor(cy * WORLD.chunkSize + WORLD.chunkSize / 2);
      const id = classifyBiome(wx, wy).id;
      counts.set(id, (counts.get(id) ?? 0) + 1);
    }
  }
  const total = [...counts.values()].reduce((sum, value) => sum + value, 0) || 1;
  const seen = [...counts.entries()].sort((a, b) => b[1] - a[1]).map(([id, count]) => ({ id, count, pct: count / total }));
  const missing = SPEC_BIOME_IDS.filter(id => !counts.has(id));
  const audit = { seen, missing, total, spec: SPEC_BIOME_IDS };
  cache.set(key, audit);
  if (cache.size > 24) cache.delete(cache.keys().next().value);
  return audit;
}

