    const water = ['deep_ocean', 'ocean', 'shallow_water', 'river', 'lake', 'swamp'].includes(tile.biome);
    const asset = water ? this.catalog.waterForBiome(tile.biome) : this.catalog.terrainForBiome(tile.biome);
    return {
