export function collisionWorldBounds(asset, wx, wy, tileSize = 32) {
  const shapes = asset?.collision ?? [];
  return shapes.map(shape => localShapeToWorld(shape, wx, wy, tileSize));
}

export function blocksMovement(asset) {
  return Boolean(asset?.physics?.blocksMovement);
}

export function blocksLight(asset) {
  return Boolean(asset?.render?.occluder);
}

export function localShapeToWorld(shape, wx, wy, tileSize) {
  const ox = wx * tileSize;
  const oy = wy * tileSize;
  if (shape.type === 'rect') return { ...shape, x: ox + shape.x, y: oy + shape.y };
  if (shape.type === 'circle') return { ...shape, cx: ox + shape.cx, cy: oy + shape.cy };
  if (shape.type === 'polygon') return { ...shape, points: shape.points.map(([x, y]) => [ox + x, oy + y]) };
  return shape;
}

export const DRAW_LAYER_ORDER = Object.freeze({
  terrain: 0,
  decal: 10,
  object: 20,
  canopy: 30,
  entity: 40,
  effect: 50,
  lighting: 60
});

export function drawSortKey(render, wy = 0, elevation = 0) {
  const layer = DRAW_LAYER_ORDER[render?.drawLayer ?? 'object'] ?? 20;
  if (render?.sort === 'fixed') return layer * 1000000;
  if (render?.sort === 'elevationThenY') return layer * 1000000 + elevation * 10000 + wy;
  return layer * 1000000 + wy;
}

export function applyBlend(ctx, render) {
  const blend = render?.blend ?? 'normal';
  ctx.globalCompositeOperation = blend === 'add' ? 'lighter' : blend === 'multiply' ? 'multiply' : blend === 'screen' ? 'screen' : blend === 'overlay' ? 'overlay' : 'source-over';
}

export function animationFrame(animation, timeSeconds, direction = 'S') {
  if (!animation) return { frame: 0, direction };
  const directions = animation.directions ?? ['OMNI'];
  const resolvedDirection = directions.includes(direction) ? direction : directions[0];
  const frameCount = Math.max(1, animation.frames ?? 1);
  const frame = animation.loop
    ? Math.floor(timeSeconds * (animation.fps ?? 1)) % frameCount
    : Math.min(frameCount - 1, Math.floor(timeSeconds * (animation.fps ?? 1)));
  return { frame, direction: resolvedDirection };
}

export function activeFrameEvents(animation, frame) {
  return (animation?.events ?? []).filter(event => event.frame === frame);
}

